# -*- coding: utf-8 -*-
"""Rebuild a bind_init action directory so a model can replay the real dispatch.

The point is fidelity: the agent under test must read the *same* files the Host writes
at runtime — `task_prompt_stub_*.md`, `prompt_*.md`, `method_*.md`, `bundle.yaml`,
`environment_capabilities.yaml`, `refs/**` — and Edit the *same* engine-written
skeleton `parts/*.yaml`. Only two things differ from the recorded run:

  * the engine skeleton is regenerated by the current engine, so intake fixes apply;
  * `method_*.md` is re-rendered from the current skill, so prompt edits apply.

Usage:
    python evals/tg_init/build_replay.py --source <recorded bind_init dir> \
        --repo <test script root> --out <replay dir>
"""

from __future__ import annotations

import argparse
import shutil
import sys
from pathlib import Path
from typing import Any

import yaml

REPO_ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO_ROOT / "engines" / "testcase-generation"))

from testcase_agent import bind_parts as BP  # noqa: E402
from testcase_agent import test_repo as TR  # noqa: E402

SKILL_REFS = REPO_ROOT / "skills" / "bind-init" / "references"

# Which skill reference backs each axis method file, and which refs get materialized
# next to it. Mirrors what the Host does when it slices the skill.
AXIS_METHOD = {
    "bind": ("columns.md", ["test-script-repo.md", "column-binding-edge-cases.md"]),
    "harness": ("harness.md", ["test-script-repo.md", "harness-edge-cases.md"]),
}


def _load(path: Path) -> dict[str, Any]:
    doc = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    return doc if isinstance(doc, dict) else {}


def render_method(axis: str) -> str:
    """Skill reference + the pointer footer the Host appends."""
    name, refs = AXIS_METHOD[axis]
    body = (SKILL_REFS / name).read_text(encoding="utf-8").rstrip("\n")
    pointers = "\n".join(f"- `references/{r}`" for r in refs)
    materialized = "\n".join(f"- `refs/{axis}/{r}`" for r in refs)
    return (
        f"{body}\n\n## 指针\n\n{pointers}\n\n"
        f"## Materialized refs (session-local)\n\n{materialized}\n"
    )


def build(source: Path, repo: Path, out: Path, project: Path | None) -> dict[str, Any]:
    if out.exists():
        shutil.rmtree(out)
    out.mkdir(parents=True)

    # 1. Verbatim Host-written context.
    for name in (
        "bundle.yaml",
        "captured.yaml",
        "environment_capabilities.yaml",
        "prompt.md",
        "prompt_bind.md",
        "prompt_harness.md",
        "review_axes.yaml",
        "session_state.yaml",
    ):
        src = source / name
        if src.is_file():
            shutil.copy2(src, out / name)
    if (source / "refs").is_dir():
        shutil.copytree(source / "refs", out / "refs")

    # 2. Engine skeleton, regenerated by the current engine.
    inventory = TR.scan(repo)
    contract = TR.contract_from_inventory(inventory)
    scan = {"kind": contract.get("kind") or "script_repo", "inventory": inventory, "contract": contract}
    identity = _load(source / "parts" / ".engine" / "bind.owned.yaml").get("artifact_identity") or {}
    emitted = BP.emit_bind_parts(out / "parts", scan=scan, identity=identity)

    # 3. Method files re-rendered from the current skill.
    for axis in AXIS_METHOD:
        (out / f"method_{axis}.md").write_text(render_method(axis), encoding="utf-8")
    if (source / "method.md").is_file():
        shutil.copy2(source / "method.md", out / "method.md")

    # 4. Stubs, repointed at the replay directory.
    chunks = sorted(p.name for p in (out / "parts").glob("bind[0-9]*.yaml"))
    slices = ["harness"] + [p.removesuffix(".yaml") for p in chunks]
    written: list[str] = []
    for slice_id in slices:
        axis = "harness" if slice_id == "harness" else "bind"
        part = f"parts/{slice_id}.yaml"
        others = [f"parts/{s}.yaml" for s in [*slices, "bind"] if s != slice_id]
        columns = ""
        if axis == "bind":
            names = [
                str(c.get("name") if isinstance(c, dict) else c)
                for c in (_load(out / "parts" / f"{slice_id}.yaml").get("columns") or [])
            ]
            keys = list((_load(out / "parts" / f"{slice_id}.yaml").get("mapping") or {}))
            columns = f"（本路 {len(keys)} 列：{', '.join(keys)}）" if keys else ""
            del names
        stub = out / f"task_prompt_stub_{slice_id}.md"
        stub.write_text(
            "\n".join(
                [
                    "action_id=bind_init",
                    "actor_id=tg-analyst",
                    "run_id=REPLAY",
                    "Follow ONLY these session files (read them first; do not invent extra goals):",
                    f"  prompt: {(out / f'prompt_{axis}.md').as_posix()}",
                    f"  method: {(out / f'method_{axis}.md').as_posix()}",
                    f"  bundle: {(out / 'bundle.yaml').as_posix()}",
                    f"session_dir: {out.as_posix()}",
                    (
                        f"pilot_cli commands must pass --project {project.as_posix()}"
                        if project
                        else ""
                    ),
                    f"write: {(out / part).as_posix()}",
                    f"forbid_read: {', '.join(others)}",
                    f"environment: {(out / 'environment_capabilities.yaml').as_posix()}",
                    "USER QUESTION (answer this against the CodeMap / minimal source windows):",
                    f"AXIS={slice_id}",
                    f"FOCUS: {part}{columns}",
                    f"SLICE_ID={slice_id}",
                    f"Read only the method path in this stub. Write only `{part}`. "
                    "Do not Write the other axis or canonical products.",
                    "Hard stop: this Task answers ONLY the FOCUS / SLICE_ID above.",
                    "Return a short summary when done.",
                    "Do NOT finalize; Host `pilot_run` holds finalize for `bind_init`.",
                ]
            ).replace("\n\n", "\n")
            + "\n",
            encoding="utf-8",
        )
        written.append(stub.name)

    return {"emitted": emitted, "slices": slices, "stubs": written, "out": str(out)}


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--source", required=True, type=Path)
    ap.add_argument("--repo", required=True, type=Path)
    ap.add_argument("--out", required=True, type=Path)
    ap.add_argument("--project", type=Path, default=None)
    args = ap.parse_args(argv)
    info = build(args.source.resolve(), args.repo.resolve(), args.out.resolve(), args.project)
    print(yaml.safe_dump(info, allow_unicode=True, sort_keys=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())
